  @state newTrackIds = {}  @ 35   -- { trackKey → id }; newTrack addressing, refreshed by snapshot/applyOps
  @state actualState = nil  @ 36   -- in-memory model of REAPER's actual side (the diff's "actual"); local writes
  @state pinCorrection = nil  @ 38   -- { [guid]=pinMaps } awaiting a post-grow re-assert; one coalesced reaper.defer
