  @state CU_IDENT = 'JS:Continuum Utility'  @ 42
  @state CC_IDENT = 'JS:Continuum CC'  @ 43
  @state AUTO_BUS = 126  @ 44   -- its CC-propagation bus; sends on it aren't wiring's
  @state compiledCache = nil  @ 52   -- { graph, ctx, reach } | nil; cleared on every graph swap
  @state PIN_GROW_FIXED_VERSION = 7075  @ 74   -- maj*1000+min of the fix; nil = unfixed, guard always holds
  @state jsfxTraitsMemo = {}  @ 157
  @state CU_MODE_TO_FLOAT = { busRoute = 0, merge = 1 }  @ 868
  @state MASTER_KEY = '__master__'  @ 1095

