  -- compiled-graph cache: one clone+compile per structural change, pulled by wv
  @fn adjacencies(g)  @ 102-109
  @fn reaches(adj, start, target)  @ 112-123
      -- Directed reachability over one of adjacencies' lists: true iff target lies downstream of start.
  @fn ensureCompiled()  @ 126-135
      -- Lazy past ensureLoaded so the nil reload-sentinel resolves before any compile.
  @fn parseJSFXMidiTraits(content)  @ 139-151
